from collections import Counter

def comps_of(g, col):
    h, w = len(g), len(g[0])
    cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] == col}
    out = []
    while cells:
        c = cells.pop(); comp = [c]; st = [c]
        while st:
            r, cc = st.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                n = (r + dr, cc + dc)
                if n in cells:
                    cells.remove(n); comp.append(n); st.append(n)
        out.append(comp)
    return out

